// ─── Cálculo de Horários Disponíveis em Intervalos Compactos (Fuso SP Imune a Servidor) ───
const dadosInput = $('When Executed by Another Workflow').first().json;
const eventsData = $input.first()?.json || {};
const googleEvents = Array.isArray(eventsData.items) ? eventsData.items : [];

const duracao = Number(dadosInput.duracao_minutos || 30);
const dataAlvoStr = (dadosInput.data || '').trim().toLowerCase();

const formatterSP = new Intl.DateTimeFormat('en-US', {
  timeZone: 'America/Sao_Paulo',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
  hour12: false
});

function getSPParts(dateObj) {
  const parts = formatterSP.formatToParts(dateObj);
  const m = {};
  parts.forEach(p => m[p.type] = p.value);
  return {
    ano: Number(m.year),
    mes: Number(m.month) - 1,
    dia: Number(m.day),
    hora: Number(m.hour === '24' ? '0' : m.hour),
    minuto: Number(m.minute)
  };
}

const agora = new Date();
const agoraParts = getSPParts(agora);

let ano = agoraParts.ano;
let mes = agoraParts.mes;
let dia = agoraParts.dia;

if (dataAlvoStr === 'amanha' || dataAlvoStr === 'amanhã') {
  const d = new Date(agoraParts.ano, agoraParts.mes, agoraParts.dia + 1);
  ano = d.getFullYear();
  mes = d.getMonth();
  dia = d.getDate();
} else if (dataAlvoStr.match(/^\d{4}-\d{2}-\d{2}$/)) {
  const [y, m, d] = dataAlvoStr.split('-').map(Number);
  ano = y;
  mes = m - 1;
  dia = d;
} else if (dataAlvoStr.match(/^\d{2}\/\d{2}\/\d{4}$/)) {
  const [d, m, y] = dataAlvoStr.split('/').map(Number);
  ano = y;
  mes = m - 1;
  dia = d;
}

const targetDateObj = new Date(ano, mes, dia);
const hojeDateObj = new Date(agoraParts.ano, agoraParts.mes, agoraParts.dia);

if (targetDateObj < hojeDateObj) {
  return [{
    json: {
      sucesso: false,
      mensagem: 'A data solicitada já passou. Por favor, escolha uma data futura.'
    }
  }];
}

const dataFormatadaStr = `${String(dia).padStart(2, '0')}/${String(mes + 1).padStart(2, '0')}/${ano}`;
const isoDateStr = `${ano}-${String(mes + 1).padStart(2, '0')}-${String(dia).padStart(2, '0')}`;

// 🇧🇷 1. Cálculo Automático de Feriados Nacionais Brasileiros
function getPascoa(y) {
  const a = y % 19, b = Math.floor(y / 100), c = y % 100;
  const d = Math.floor(b / 4), e = b % 4, f = Math.floor((b + 8) / 25);
  const g = Math.floor((b - f + 1) / 3), h = (19 * a + b - d - g + 15) % 30;
  const i = Math.floor(c / 4), k = c % 4, L = (32 + 2 * e + 2 * i - h - k) % 7;
  const m = Math.floor((a + 11 * h + 22 * L) / 451);
  const month = Math.floor((h + L - 7 * m + 114) / 31);
  const day = ((h + L - 7 * m + 114) % 31) + 1;
  return new Date(y, month - 1, day);
}

function obterFeriadosBR(y) {
  const feriados = {};
  feriados[`${y}-01-01`] = 'Ano Novo (Confraternização Universal)';
  feriados[`${y}-04-21`] = 'Tiradentes';
  feriados[`${y}-05-01`] = 'Dia do Trabalho';
  feriados[`${y}-09-07`] = 'Independência do Brasil';
  feriados[`${y}-10-12`] = 'Nossa Senhora Aparecida';
  feriados[`${y}-11-02`] = 'Finados';
  feriados[`${y}-11-15`] = 'Proclamação da República';
  feriados[`${y}-11-20`] = 'Dia da Consciência Negra';
  feriados[`${y}-12-25`] = 'Natal';

  const pascoa = getPascoa(y);
  const sextaSanta = new Date(pascoa); sextaSanta.setDate(pascoa.getDate() - 2);
  feriados[`${y}-${String(sextaSanta.getMonth() + 1).padStart(2, '0')}-${String(sextaSanta.getDate()).padStart(2, '0')}`] = 'Sexta-feira Santa';

  const carnavalSeg = new Date(pascoa); carnavalSeg.setDate(pascoa.getDate() - 48);
  feriados[`${y}-${String(carnavalSeg.getMonth() + 1).padStart(2, '0')}-${String(carnavalSeg.getDate()).padStart(2, '0')}`] = 'Carnaval';

  const carnavalTer = new Date(pascoa); carnavalTer.setDate(pascoa.getDate() - 47);
  feriados[`${y}-${String(carnavalTer.getMonth() + 1).padStart(2, '0')}-${String(carnavalTer.getDate()).padStart(2, '0')}`] = 'Carnaval';

  const corpus = new Date(pascoa); corpus.setDate(pascoa.getDate() + 60);
  feriados[`${y}-${String(corpus.getMonth() + 1).padStart(2, '0')}-${String(corpus.getDate()).padStart(2, '0')}`] = 'Corpus Christi';

  return feriados;
}

const feriadosAno = obterFeriadosBR(ano);
if (feriadosAno[isoDateStr]) {
  const nomeFeriado = feriadosAno[isoDateStr];
  return [{
    json: {
      sucesso: false,
      mensagem: `O estabelecimento estará fechado no dia ${dataFormatadaStr} por conta do feriado nacional (${nomeFeriado}).`
    }
  }];
}

// 🔒 2. Verificação de Datas Bloqueadas no Cadastro/DB
const datasBloqStr = String(dadosInput.datas_bloqueadas || '');
if (datasBloqStr.includes(isoDateStr) || datasBloqStr.includes(dataFormatadaStr)) {
  return [{
    json: {
      sucesso: false,
      mensagem: `O estabelecimento estará fechado na data ${dataFormatadaStr} (data bloqueada).`
    }
  }];
}

// 🔒 3. Verificação de Feriados e Eventos no Google Calendar
const palavrasChaveBloqueio = ['feriado', 'fechado', 'bloqueado', 'folga', 'recesso', 'independência', 'independencia', 'não atende', 'nao atende', 'sem atendimento'];

const ehFeriadoOuBloqueadoGC = googleEvents.some(ev => {
  if (ev.status === 'cancelled') return false;

  const summary = (ev.summary || '').toLowerCase();
  const desc = (ev.description || '').toLowerCase();
  const temPalavraChave = palavrasChaveBloqueio.some(p => summary.includes(p) || desc.includes(p));

  if (ev.start && ev.start.date) {
    const sDate = ev.start.date;
    const eDate = ev.end?.date || sDate;
    if (isoDateStr >= sDate && isoDateStr < eDate) return true;
    if (sDate === isoDateStr) return true;
  }

  if (temPalavraChave) {
    if (ev.start?.dateTime) {
      const sParts = getSPParts(new Date(ev.start.dateTime));
      if (sParts.ano === ano && sParts.mes === mes && sParts.dia === dia) {
        return true;
      }
    }
  }

  return false;
});

if (ehFeriadoOuBloqueadoGC) {
  return [{
    json: {
      sucesso: false,
      mensagem: `O estabelecimento estará fechado na data ${dataFormatadaStr} por conta de feriado ou bloqueio na agenda.`
    }
  }];
}

const isHoje = (ano === agoraParts.ano && mes === agoraParts.mes && dia === agoraParts.dia);
const limiteAntecedenciaMinutos = (agoraParts.hora * 60 + agoraParts.minuto) + 30;

function hhmmParaMinutos(str) {
  if (!str) return 0;
  const [h, m] = String(str).split(':').map(Number);
  return h * 60 + m;
}

function minutosParaHhmm(min) {
  const h = Math.floor(min / 60);
  const m = min % 60;
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
}

function obterHorariosDoDia(diaSem, d) {
  let hPorDia = d.horarios_por_dia;
  if (typeof hPorDia === 'string') {
    try { hPorDia = JSON.parse(hPorDia); } catch(e) {}
  }

  const mapaVariantes = {
    1: ['1', 'segunda', 'segunda-feira', 'segunda_feira'],
    2: ['2', 'terca', 'terça', 'terca-feira', 'terça-feira', 'terca_feira', 'terça_feira'],
    3: ['3', 'quarta', 'quarta-feira', 'quarta_feira'],
    4: ['4', 'quinta', 'quinta-feira', 'quinta_feira'],
    5: ['5', 'sexta', 'sexta-feira', 'sexta_feira'],
    6: ['6', 'sabado', 'sábado', 'sabado_feira'],
    7: ['7', 'domingo']
  };

  const chavesProcurar = mapaVariantes[diaSem] || [String(diaSem)];

  let configDia = null;
  if (hPorDia && typeof hPorDia === 'object') {
    const chavesObjeto = Object.keys(hPorDia);
    for (const key of chavesObjeto) {
      const keyNorm = key.trim().toLowerCase();
      if (chavesProcurar.some(varKey => varKey === keyNorm)) {
        configDia = hPorDia[key];
        break;
      }
    }
  }

  if (configDia === false || (configDia && configDia.fechado === true)) {
    return { aberto: false };
  }

  if (configDia && typeof configDia === 'object') {
    return {
      aberto: true,
      manhaIni: configDia.manha_inicio || configDia.manha?.[0] || d.turno_manha_inicio || '08:00',
      manhaFim: configDia.manha_fim    || configDia.manha?.[1] || d.turno_manha_fim    || '12:00',
      tardeIni: configDia.tarde_inicio || configDia.tarde?.[0] || d.turno_tarde_inicio || '13:00',
      tardeFim: configDia.tarde_fim    || configDia.tarde?.[1] || d.turno_tarde_fim    || '19:00',
      semManha: configDia.sem_manha === true || configDia.manha === null,
      semTarde: configDia.sem_tarde === true || configDia.tarde === null
    };
  }

  return {
    aberto: true,
    manhaIni: d.turno_manha_inicio || '08:00',
    manhaFim: d.turno_manha_fim    || '12:00',
    tardeIni: d.turno_tarde_inicio || '13:00',
    tardeFim: d.turno_tarde_fim    || '19:00',
    semManha: false,
    semTarde: false
  };
}

const dateSPForDay = new Date(Date.UTC(ano, mes, dia, 12, 0, 0));
let diaSemana = dateSPForDay.getUTCDay();
if (diaSemana === 0) diaSemana = 7;

const horDia = obterHorariosDoDia(diaSemana, dadosInput);

if (!horDia.aberto) {
  return [{
    json: {
      sucesso: false,
      mensagem: `O estabelecimento não abre neste dia da semana (${dataFormatadaStr}).`
    }
  }];
}

const manhaIni = hhmmParaMinutos(horDia.manhaIni);
const manhaFim = hhmmParaMinutos(horDia.manhaFim);
const tardeIni = hhmmParaMinutos(horDia.tardeIni);
const tardeFim = hhmmParaMinutos(horDia.tardeFim);

const ocupados = googleEvents.filter(ev => {
  if (!ev.start || (!ev.start.dateTime && !ev.start.date)) return false;
  if (ev.status === 'cancelled') return false;

  const sRaw = new Date(ev.start.dateTime || (ev.start.date + 'T00:00:00-03:00'));
  const sParts = getSPParts(sRaw);

  return sParts.ano === ano && sParts.mes === mes && sParts.dia === dia;
}).map(ev => {
  const sRaw = new Date(ev.start.dateTime || (ev.start.date + 'T00:00:00-03:00'));
  const eRaw = new Date(ev.end.dateTime   || (ev.end.date   + 'T23:59:59-03:00'));

  const sParts = getSPParts(sRaw);
  const eParts = getSPParts(eRaw);

  return {
    iniMin: sParts.hora * 60 + sParts.minuto,
    fimMin: eParts.hora * 60 + eParts.minuto
  };
});

function calcularSlotsDaJanela(inicioJanela, fimJanela) {
  const slots = [];
  for (let min = inicioJanela; min + duracao <= fimJanela; min += 30) {
    if (isHoje && min < limiteAntecedenciaMinutos) {
      continue;
    }
    const conflito = ocupados.some(o => min < o.fimMin && (min + duracao) > o.iniMin);
    if (!conflito) {
      slots.push(min);
    }
  }
  return slots;
}

function agruparEmTextoIntervalos(minutosArray, inicioJanela, fimJanela) {
  if (!minutosArray || minutosArray.length === 0) return null;

  const blocos = [];
  let iniBloco = minutosArray[0];
  let fimBloco = minutosArray[0] + duracao;

  for (let i = 1; i < minutosArray.length; i++) {
    const minAtual = minutosArray[i];
    if (minAtual === fimBloco) {
      fimBloco = minAtual + duracao;
    } else if (minAtual < fimBloco) {
      fimBloco = Math.max(fimBloco, minAtual + duracao);
    } else {
      blocos.push({ inicio: iniBloco, fim: fimBloco });
      iniBloco = minAtual;
      fimBloco = minAtual + duracao;
    }
  }
  blocos.push({ inicio: iniBloco, fim: fimBloco });

  const textosBlocos = blocos.map(b => `${minutosParaHhmm(b.inicio)} às ${minutosParaHhmm(b.fim)}`);

  let textoLivre = '';
  if (textosBlocos.length === 1) {
    textoLivre = `das ${textosBlocos[0]}`;
  } else if (textosBlocos.length === 2) {
    textoLivre = `das ${textosBlocos[0]} e das ${textosBlocos[1]}`;
  } else {
    textoLivre = `das ${textosBlocos.slice(0, -1).join(', das ')} e das ${textosBlocos[textosBlocos.length - 1]}`;
  }

  const ocupadosJanela = ocupados.filter(o => o.fimMin > inicioJanela && o.iniMin < fimJanela);
  if (ocupadosJanela.length > 0 && blocos.length > 1) {
    const textosOcupados = ocupadosJanela.map(o => {
      const ini = Math.max(o.iniMin, inicioJanela);
      const fim = Math.min(o.fimMin, fimJanela);
      return `${minutosParaHhmm(ini)} às ${minutosParaHhmm(fim)}`;
    });
    return `${textoLivre} (ocupado das ${textosOcupados.join(', ')})`;
  }

  return textoLivre;
}

const slotsManha = !horDia.semManha ? calcularSlotsDaJanela(manhaIni, manhaFim) : [];
const slotsTarde = !horDia.semTarde ? calcularSlotsDaJanela(tardeIni, tardeFim) : [];

const intervalosManhaStr = agruparEmTextoIntervalos(slotsManha, manhaIni, manhaFim);
const intervalosTardeStr = agruparEmTextoIntervalos(slotsTarde, tardeIni, tardeFim);

const todosSlotsMinutos = [...slotsManha, ...slotsTarde];
const todosSlotsHHMM = todosSlotsMinutos.map(minutosParaHhmm);

if (todosSlotsMinutos.length === 0) {
  return [{
    json: {
      sucesso: false,
      mensagem: `Não há horários disponíveis para ${dataFormatadaStr}.`
    }
  }];
}

let mensagemResumo = `Horários disponíveis para ${dataFormatadaStr}:\n`;
if (intervalosManhaStr) {
  mensagemResumo += `• No período da manhã: ${intervalosManhaStr}\n`;
}
if (intervalosTardeStr) {
  mensagemResumo += `• No período da tarde: ${intervalosTardeStr}\n`;
}

return [{
  json: {
    sucesso: true,
    data: dataFormatadaStr,
    horarios: todosSlotsHHMM,
    intervalos_manha: intervalosManhaStr || 'Sem horários',
    intervalos_tarde: intervalosTardeStr || 'Sem horários',
    mensagem: mensagemResumo.trim()
  }
}];
